{{ frappe.utils.fmt_money(v or 0, currency="INR") }}
{%- endmacro -%}

{%- set amount_in_words = frappe.utils.money_in_words(doc.total or 0, "INR") -%}

{%- set ns = namespace(has_igst=false) -%}
