    {%- if row.igst_rate -%}{%- set ns.has_igst = true -%}{%- endif -%}
{%- endfor -%}

<style>
@page { size: A4; margin: 10mm 10mm 12mm 10mm; }
html, body { margin: 0; padding: 0; background: #fff; font-family: Arial, Helvetica, sans-serif; color: #222; font-size: 10px; }
* { box-sizing: border-box; }
.dish-container { width: 100%; border-collapse: collapse; border: 2px solid #1c3f60; }
.dish-container > thead { display: table-header-group; }
.dish-container > tfoot { display: table-footer-group; }
.header-wrapper-cell { padding: 0; border-bottom: 2px solid #1c3f60; }
.brand-header-table { width: 100%; border-collapse: collapse; }
.brand-header-table td { border: 1px solid #1c3f60; padding: 6px 10px; vertical-align: middle; }
.brand-name { font-size: 15px; font-weight: bold; color: #11466a; letter-spacing: .3px; }
.brand-tagline { font-size: 7px; color: #666; font-style: italic; }
.doc-meta-box { font-size: 8px; text-align: center; line-height: 1.5; }
.title-bar-table { width: 100%; table-layout: fixed; border-collapse: collapse; }
.title-bar-table td { background: #c8631a; color: #fff; font-size: 14px; font-weight: bold; padding: 6px 12px; letter-spacing: .3px; white-space: nowrap; overflow: hidden; }
.title-bar-table td.block { width: 50%; }
.info-table { width: 100%; border-collapse: collapse; }
.info-table td { border: 1px solid #999; padding: 5px 8px; font-size: 9px; vertical-align: top; }
.info-table td.hdr { font-weight: bold; background: #eef3f7; color: #11466a; }
.section-title-row td { background: #11466a; color: #fff; font-weight: bold; text-align: center; font-size: 9px; text-transform: uppercase; padding: 4px 6px; }
.items-table { width: 100%; border-collapse: collapse; }
.items-table th { background: #11466a; color: #fff; border: 1px solid #1c3f60; padding: 5px 4px; font-size: 9px; text-transform: uppercase; }
.items-table td { border: 1px solid #999; padding: 5px 4px; font-size: 9px; line-height: 1.3; vertical-align: top; }
.items-table tbody tr { page-break-inside: avoid; break-inside: avoid; }
.col-sl { width: 6%; text-align: center; }
.col-item { width: 30%; word-break: break-word; }
.col-hsn { width: 9%; text-align: center; }
.col-qty { width: 8%; text-align: center; }
.col-rate { width: 10%; text-align: right; }
.col-gst-full { width: 12%; text-align: center; }
.col-gst-half { width: 6%; text-align: center; }
.col-amount { width: 15%; text-align: right; font-weight: bold; }
.col-warranty { width: 10%; text-align: center; }
.words-box { border: 1px solid #1c3f60; }
.words-box-title { background: #11466a; color: #fff; padding: 4px 6px; font-size: 8px; font-weight: bold; text-transform: uppercase; }
.words-box-content { padding: 6px 8px; font-size: 9px; font-weight: bold; text-transform: capitalize; border: 1px solid #999; border-top: none; }
.summary-financial-block { page-break-inside: avoid; break-inside: avoid; margin-top: 6px; }
.totals-table { width: 100%; table-layout: fixed; border-collapse: collapse; box-sizing: border-box; }
.totals-table td { border: 1px solid #999; padding: 5px 8px; font-size: 9px; }
.totals-table td.label { font-weight: bold; text-align: right; width: 70%; }
.totals-table td.value { text-align: right; width: 30%; }
.totals-table tr.grand-total td { font-weight: bold; background: #eef6fb; }
.signoff-table { width: 100%; border-collapse: collapse; page-break-inside: avoid; break-inside: avoid; }
.signoff-table td { border: 1px solid #999; padding: 5px 8px; font-size: 9px; vertical-align: top; }
.signoff-table td.hdr { font-weight: bold; background: #eef3f7; }
.footer-wrapper-cell { padding: 0; border-top: 2px solid #1c3f60; background: #fff; }
.footer-inner-block { width: 100%; padding: 6px 12px; }
.product-range-ribbon { background: #11466a; color: #fff; text-align: center; font-size: 8px; font-weight: bold; padding: 5px 6px; letter-spacing: .3px; width: 100%; margin-top: 4px; }
.spacer { height: 6px; }
@media print {
    html, body { margin: 0; padding: 0; width: 100%; background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
}
