            <div class="brand-name">ENERTECH UPS PVT. LTD.</div>
            <div class="brand-tagline">Answering All Power Needs</div>
        </td>
        <td style="width:40%;">
            <div class="doc-meta-box">
                Document No – EUPL/MKTG/FR/01<br>
                REV. No. – 01<br>
                Updated-1.10.2017
            </div>
        </td>
    </tr>
</table>
<table class="title-bar-table">
    <tr>
        <td class="block">DATE.: {{ frappe.utils.formatdate(doc.date,"dd/MM/yyyy") if doc.date else "" }}</td>
        <td class="block">DISH NO. : {{ doc.dish_no or "" }}</td>
    </tr>
</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<table class="info-table">
    <tr>
        <td class="hdr" style="width:33%;">Customer Details</td>
        <td class="hdr" style="width:34%;">Purchase Order No.</td>
        <td class="hdr" style="width:33%;">Mode/Terms of Payment</td>
    </tr>
    <tr>
        <td rowspan="4">
            <div style="font-weight:bold;">{{ doc.customer_name or doc.customer or "" }}</div>
            <div style="margin-top:3px; color:#444;">{{ doc.customer_address or "" }}</div>
            {% if doc.contact_no %}<div style="margin-top:3px;">Contact No: {{ doc.contact_no }}</div>{% endif %}
            {% if doc.gst_no %}<div style="margin-top:3px; font-weight:bold;">GST NO : {{ doc.gst_no }}</div>{% endif %}
        </td>
        <td>{{ doc.purchase_order_no or "" }}</td>
        <td>{{ doc.modeterms_of_payment or "" }}</td>
    </tr>
    <tr>
        <td class="hdr">Order Date.</td>
        <td class="hdr">Bank Guarranty Details If Any</td>
    </tr>
    <tr>
        <td>{{ frappe.utils.formatdate(doc.order_date,"dd-MMM-yy") if doc.order_date else "" }}</td>
        <td>{{ doc.bank_guarantee_details or "" }}</td>
    </tr>
    <tr>
        <td class="hdr">Expected Delivery</td>
        <td class="hdr">C Form Status Y/N:</td>
    </tr>
    <tr>
        <td class="hdr" style="width:33%;">Buyer Details</td>
        <td>{{ frappe.utils.formatdate(doc.expected_delivery,"dd/MM/yyyy") if doc.expected_delivery else "" }}</td>
        <td>{{ doc.c_form_status or "" }}</td>
    </tr>
    <tr>
        <td rowspan="2">
            <div style="font-weight:bold;">{{ doc.buyers_name or doc.buyer or "" }}</div>
            <div style="margin-top:3px; color:#444;">{{ doc.buyer_address or "" }}</div>
            {% if doc.buyer_contact_no %}<div style="margin-top:3px;">Contact No: {{ doc.buyer_contact_no }}</div>{% endif %}
            {% if doc.buyers_email %}<div style="margin-top:3px;">Email: {{ doc.buyers_email }}</div>{% endif %}
            {% if doc.bueyer_gst_no %}<div style="margin-top:3px; font-weight:bold;">GST NO : {{ doc.bueyer_gst_no }}</div>{% endif %}
        </td>
        <td class="hdr" colspan="2">Mode of Dispatch</td>
    </tr>
    <tr>
        <td colspan="2" style="font-weight:bold;">{{ doc.mode_of_dispatch or "" }}</td>
    </tr>
</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<table class="info-table" style="margin-top:6px;">
    <tr>
        <td class="hdr" style="width:50%;">Invoice To.</td>
        <td class="hdr" style="width:50%;">Special Note:</td>
    </tr>
    <tr>
        <td>
            <div style="font-weight:bold;">{{ doc.invoice_to_name or "" }}</div>
            <div style="margin-top:3px; color:#444;">{{ doc.invoice_to_address or "" }}</div>
        </td>
        <td>{{ doc.special_note or "" }}</td>
    </tr>
</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<table class="info-table" style="margin-top:6px;">
    <tr>
        <td class="hdr" style="width:50%;">Dispatch TO</td>
        <td class="hdr" style="width:50%;">Terms of Delivery</td>
    </tr>
    <tr>
        <td>
            <div style="font-weight:bold;">{{ doc.dispatch_to_name or "" }}</div>
            <div style="margin-top:3px; color:#444;">{{ doc.dispatch_to_address or "" }}</div>
        </td>
        <td style="color:#1c4fa0; font-weight:bold;">{{ doc.terms_of_delivery or "" }}</td>
    </tr>
</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<table class="items-table" style="margin-top:6px;">
    <thead>
        <tr>
            <th class="col-sl">No.</th>
            <th class="col-item">Item / Description</th>
            <th class="col-warranty">Warranty</th>
            <th class="col-hsn">HSN Code</th>
            <th class="col-qty">Quantity</th>
            <th class="col-rate">Rate</th>
            {%- if ns.has_igst -%}
            <th class="col-gst-full">IGST</th>
            {%- else -%}
            <th class="col-gst-half">CGST</th>
            <th class="col-gst-half">SGST</th>
            {%- endif -%}
            <th class="col-amount">Amount</th>
        </tr>
    </thead>
    <tbody>
        {% for row in doc.items %}
        <tr>
            <td class="col-sl">{{ loop.index }}</td>
            <td class="col-item">
                <div style="font-weight:bold;">{{row.item_code }}</div>
                <div style="font-weight:bold;">{{row.item_name }}</div>
                {% if row.description %}
                <div style="margin-top:2px; font-size:8.5px; color:#444; white-space:pre-wrap;">{{ row.description }}</div>
                {% endif %}
            </td>
            <td class="col-warranty">{{ row.warranty or "" }}</td>
            <td class="col-hsn">{{ row.hsn_code or "" }}</td>
            <td class="col-qty">{{ row.qty or "" }} {{ row.uom or "" }}</td>
            <td class="col-rate">{{ money(row.rate) }}</td>
            {%- if ns.has_igst -%}
            <td class="col-gst-full">{{ frappe.utils.flt(row.igst_rate)|round(0)|int }}%<br>{{ money(row.igst_amount) }}</td>
            {%- else -%}
            <td class="col-gst-half">{{ frappe.utils.flt(row.cgst_rate)|round(0)|int }}%<br>{{ money(row.cgst_amount) }}</td>
            <td class="col-gst-half">{{ frappe.utils.flt(row.sgst_rate)|round(0)|int }}%<br>{{ money(row.sgst_amount) }}</td>
            {%- endif -%}
            <td class="col-amount">{{ money(row.amount) }}</td>
        </tr>
        {% endfor %}
    </tbody>
</table>"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<div class="summary-financial-block">
    <table style="width:100%; border-collapse:collapse;">
        <tr>
            <td style="width:55%; vertical-align:top; padding-right:10px; border:none;">
                <div class="words-box">
                    <div class="words-box-title">Total Amount (In Words)</div>
                    <div class="words-box-content">{{ amount_in_words }}</div>
                </div>
            </td>
            <td style="width:45%; vertical-align:top; border:none;">
                <table class="totals-table">
                    <tr>
                        <td class="label">Sub Total</td>
                        <td class="value">{{ money(doc.sub_total) }}</td>
                    </tr>
                    <tr>
                        <td class="label">GST@{{ frappe.utils.flt(doc.gst_rate)|round(0)|int }}%</td>
                        <td class="value">{{ money(doc.gst_amount) }}</td>
                    </tr>
                    <tr class="grand-total">
                        <td class="label">Total</td>
                        <td class="value">{{ money(doc.total) }}</td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>
</div>"}]
